Lemma zk_disj_ok : forall a1 n1 a2 n2 b1 c1 b2 c2,
  zatoms_lt na a1 = true -> zatoms_lt na n1 = true -> zatoms_lt na a2 = true -> zatoms_lt na n2 = true ->
  zsa a1 = SA b1 c1 -> zsa a2 = SA b2 c2 ->
  0 <= zden zv a1 - c1 < 2^64 -> 0 <= zden zv a2 - c2 < 2^64 -> 0 <= zden zv a1 < 2^64 -> 0 <= zden zv a2 < 2^64 ->
  0 <= zden zv n1 < 2^64 -> 0 <= zden zv n2 < 2^64 ->
  zden zv a1 + zden zv n1 <= zden zv a2 \/ zden zv a2 + zden zv n2 <= zden zv a1 ->
