Lemma zk_wr_ok : forall a n b c A N,
  zatoms_lt na a = true -> zatoms_lt na n = true -> zsa a = SA b c ->
  0 <= zden zv a - c < 2^64 -> 0 <= zden zv a < 2^64 -> 0 <= zden zv n < 2^64 ->
  wr_at segs m A N -> A <= zden zv a -> zden zv a + zden zv n <= A + N ->
