(* [comment removed for export] *)
Fixpoint all_rom (lo : Z) (k : nat) : bool :=
  match k with
  | O => true
  | S k' => match Lib.PropExec.seg_rom segs (Z_to_bv 64 lo) with Some _ => all_rom (lo + 1) k' | None => false end
  end.

Lemma all_rom_spec : forall k lo i, all_rom lo k = true -> lo <= i < lo + Z.of_nat k ->
  Lib.PropExec.seg_rom segs (Z_to_bv 64 i) <> None.
