Lemma zr_ok_img : forall a n b c,
  zatoms_lt na a = true -> zatoms_lt na n = true -> zsa a = SA b c ->
  0 <= zden zv a - c < 2^64 -> 0 <= zden zv a < 2^64 -> 0 <= zden zv n < 2^64 -> zden zv a + zden zv n <= 2^64 ->
  mem_inv segs m -> all_ro (zden zv a) (Z.to_nat (zden zv n)) = true -> all_rom (zden zv a) (Z.to_nat (zden zv n)) = true ->
