Ltac kx_mem t l :=
  lazymatch l with
  | nil => constr:(false)
  | cons t _ => constr:(true)
  | cons _ ?r => kx_mem t r
  end.

Ltac kx_add t l :=
  let b := kx_mem t l in
  lazymatch b with true => l | false => let l' := eval cbv [app] in (app l (cons t nil)) in l' end.

Ltac kx_atoms t l :=
  lazymatch t with
  | Z.add ?a ?b => let l1 := kx_atoms a l in kx_atoms b l1
  | Z.sub ?a ?b => let l1 := kx_atoms a l in kx_atoms b l1
  | Z.mul ?a ?b => let l1 := kx_atoms a l in kx_atoms b l1
  | Z0 => l | Zpos _ => l | Zneg _ => l
  | _ => kx_add t l
  end.

Ltac kx_idx t l :=
  lazymatch l with
  | cons t _ => constr:(O)
  | cons _ ?r => let i := kx_idx t r in constr:(S i)
  end.

Ltac kx_rz t l :=
  lazymatch t with
  | Z.add ?a ?b => let x := kx_rz a l in let y := kx_rz b l in constr:(ZAdd x y)
  | Z.sub ?a ?b => let x := kx_rz a l in let y := kx_rz b l in constr:(ZSub x y)
  | Z.mul ?a ?b => let x := kx_rz a l in let y := kx_rz b l in constr:(ZMul x y)
  | Z0 => constr:(ZL Z0) | Zpos ?p => constr:(ZL (Zpos p)) | Zneg ?p => constr:(ZL (Zneg p))
  | _ => let i := kx_idx t l in constr:(ZA i)
  end.

Ltac kx_reg_atoms x l :=
  lazymatch x with
  | Z_to_bv 64 ?t => kx_atoms t l
  | _ => kx_add constr:(bv_unsigned x) l
  end.

Ltac kx_reg_z x l :=
  lazymatch x with
  | Z_to_bv 64 ?t => kx_rz t l
  | _ => let i := kx_idx constr:(bv_unsigned x) l in constr:(ZA i)
  end.

Ltac kx_kz_atoms ks l :=
  lazymatch ks with
  | nil => l
  | cons (KZRange ?e _ _) ?r => let l1 := kx_atoms e l in kx_kz_atoms r l1
  | cons (KZAlign ?e _) ?r => let l1 := kx_atoms e l in kx_kz_atoms r l1
  | cons (KZDisj ?a1 ?n1 ?a2 ?n2) ?r =>
      let l1 := kx_atoms a1 l in let l2 := kx_atoms n1 l1 in let l3 := kx_atoms a2 l2 in let l4 := kx_atoms n2 l3 in
      kx_kz_atoms r l4
  | cons (KZWr ?a ?n) ?r => let l1 := kx_atoms a l in let l2 := kx_atoms n l1 in kx_kz_atoms r l2
  | cons (KZImg _ _) ?r => kx_kz_atoms r l
  | cons (KZWord ?a _ ?v) ?r => let l1 := kx_atoms a l in let l2 := kx_atoms v l1 in kx_kz_atoms r l2
  | cons (KZIdx ?tl ?T) ?r => let l1 := kx_atoms tl l in let l2 := kx_atoms T l1 in kx_kz_atoms r l2
  | cons (KZZero ?a ?n) ?r => let l1 := kx_atoms a l in let l2 := kx_atoms n l1 in kx_kz_atoms r l2
  | cons (KZTab ?a ?n _ _) ?r => let l1 := kx_atoms a l in let l2 := kx_atoms n l1 in kx_kz_atoms r l2
  | cons (KZShZ _ ?a ?n) ?r => let l1 := kx_atoms a l in let l2 := kx_atoms n l1 in kx_kz_atoms r l2
  end.

Ltac kx_kz_reify ks l :=
  lazymatch ks with
  | nil => constr:(@nil zk)
  | cons (KZRange ?e ?lo ?hi) ?r => let x := kx_rz e l in let t := kx_kz_reify r l in constr:(cons (ZKRange x lo hi) t)
  | cons (KZAlign ?e ?md) ?r => let x := kx_rz e l in let t := kx_kz_reify r l in constr:(cons (ZKAlign x md) t)
  | cons (KZDisj ?a1 ?n1 ?a2 ?n2) ?r =>
      let x1 := kx_rz a1 l in let y1 := kx_rz n1 l in let x2 := kx_rz a2 l in let y2 := kx_rz n2 l in
      let t := kx_kz_reify r l in constr:(cons (ZKDisj x1 y1 x2 y2) t)
  | cons (KZWr ?a ?n) ?r => let x := kx_rz a l in let y := kx_rz n l in let t := kx_kz_reify r l in constr:(cons (ZKWr x y) t)
  | cons (KZImg ?lo ?hi) ?r => let t := kx_kz_reify r l in constr:(cons (ZKImg lo hi) t)
  | cons (KZWord ?a ?w ?v) ?r => let x := kx_rz a l in let y := kx_rz v l in let t := kx_kz_reify r l in constr:(cons (ZKWord x w y) t)
  | cons (KZIdx ?tl ?T) ?r => let x := kx_rz tl l in let y := kx_rz T l in let t := kx_kz_reify r l in constr:(cons (ZKIdx x y) t)
  | cons (KZZero ?a ?n) ?r => let x := kx_rz a l in let y := kx_rz n l in let t := kx_kz_reify r l in constr:(cons (ZKZero x y) t)
  | cons (KZTab ?a ?n ?st ?fs) ?r =>
      let x := kx_rz a l in let y := kx_rz n l in let t := kx_kz_reify r l in constr:(cons (ZKTab x y st fs) t)
  | cons (KZShZ ?off ?a ?n) ?r =>
      let x := kx_rz a l in let y := kx_rz n l in let t := kx_kz_reify r l in constr:(cons (ZKShZ off x y) t)
  end.

Ltac kx_rr_atoms rs l :=
  lazymatch rs with
  | nil => l
  | cons (?a, ?n) ?r => let l1 := kx_atoms a l in let l2 := kx_atoms n l1 in kx_rr_atoms r l2
  end.

Ltac kx_rr_reify rs l :=
  lazymatch rs with
  | nil => constr:(@nil zreg)
  | cons (?a, ?n) ?r => let x := kx_rz a l in let y := kx_rz n l in let t := kx_rr_reify r l in constr:(cons (x, y) t)
  end.

