Definition kx_pending (segs : list Segment) (Q : machine_state -> Prop) (F : bvmap 5 word) (fc : bv 32)
  (m rom : word -> option byte) (pc : Z) (stops : list Z) (fuel : nat) (xl : list word) (zv : list Z)
  (zs : list zexp) (zks : list zk) (zrs : list zreg) : Prop :=
