Ltac kx_find_wr segs m :=
  first [ match goal with H : wr_at segs m _ _ |- _ => exact H end
        | match goal with H : u8arr segs m _ _ |- _ => exact (proj2 H) end
        | match goal with H : rw_cells segs m _ _ |- _ => exact (proj2 H) end ].

(* [comment removed for export] *)
Ltac kx_know1 segs zv xs m :=
  lazymatch goal with
  | |- kentry_ok _ _ _ (zk_ent (ZKImg ?lo ?hi)) =>
      apply (zk_img_ok segs zv xs m); [ assumption | lia | lia | lia | vm_compute; reflexivity ]
  | |- kentry_ok _ _ _ (zk_ent (ZKRange ?e ?lo ?hi)) =>
      apply (zk_range_ok segs zv xs m); [ vm_compute; reflexivity | kx_arith | kx_arith ]
  | |- kentry_ok _ _ _ (zk_ent (ZKAlign ?e ?md)) =>
      apply (zk_align_ok segs zv xs m); [ vm_compute; reflexivity | kx_arith | lia | kx_arith ]
  | |- kentry_ok _ _ _ (zk_ent (ZKDisj ?a1 ?n1 ?a2 ?n2)) =>
      let s1 := eval vm_compute in (zsa a1) in let s2 := eval vm_compute in (zsa a2) in
      lazymatch s1 with SA ?b1 ?c1 => lazymatch s2 with SA ?b2 ?c2 =>
        apply (zk_disj_ok segs zv xs m a1 n1 a2 n2 b1 c1 b2 c2);
        [ vm_compute; reflexivity | vm_compute; reflexivity | vm_compute; reflexivity | vm_compute; reflexivity
        | vm_compute; reflexivity | vm_compute; reflexivity | kx_arith .. ]
      end end
  | |- kentry_ok _ _ _ (zk_ent (ZKZero ?a ?n)) =>
      let s1 := eval vm_compute in (zsa a) in
      lazymatch s1 with SA ?b ?c =>
        first [ match goal with H : forall s, _ <= s < _ -> m (wa s) = Some (Z_to_bv 8 0) |- _ =>
                  eapply (zk_zero_ok segs zv xs m a n b c _ _);
                  [ vm_compute; reflexivity | vm_compute; reflexivity | vm_compute; reflexivity
                  | kx_arith | kx_arith | kx_arith | kx_arith | exact H | kx_arith | kx_arith ] end
              | idtac ]
      end
  | |- kentry_ok _ _ _ (zk_ent (ZKIdx _ _)) => cbn [zk_ent kentry_ok edenot]; change (bv_unsigned (Z_to_bv 64 0)) with 0%Z; lia
  | |- kentry_ok _ _ _ (zk_ent (ZKTab _ _ _ _)) => cbn [zk_ent kentry_ok edenot]; change (bv_unsigned (Z_to_bv 64 0)) with 0%Z; lia
  | |- kentry_ok _ _ _ (zk_ent (ZKShZ _ _ _)) => cbn [zk_ent kentry_ok edenot]; change (bv_unsigned (Z_to_bv 64 0)) with 0%Z; lia
  | |- kentry_ok _ _ _ (zk_ent (ZKWr ?a ?n)) =>
      let s1 := eval vm_compute in (zsa a) in
      lazymatch s1 with SA ?b ?c =>
        eapply (zk_wr_ok segs zv xs m a n b c);
        [ vm_compute; reflexivity | vm_compute; reflexivity | vm_compute; reflexivity
        | kx_arith | kx_arith | kx_arith | kx_find_wr segs m | kx_arith | kx_arith ]
      end
  | |- _ => idtac
  end.

