      lazymatch s1 with SA ?b ?c =>
        first [ lazymatch a with ZL _ => lazymatch n with ZL _ => idtac end end;
                apply (zr_ok_img segs zv xs m a n b c);
                  [ vm_compute; reflexivity | vm_compute; reflexivity | vm_compute; reflexivity
                  | kx_arith | kx_arith | kx_arith | kx_arith | assumption | vm_compute; reflexivity | vm_compute; reflexivity ]
              | match goal with H : bytes_at segs m ?A ?bs |- _ =>
                  apply (zr_ok_bytes_at segs zv xs m a n b c A bs);
                  [ vm_compute; reflexivity | vm_compute; reflexivity | vm_compute; reflexivity
                  | kx_arith | kx_arith | kx_arith | exact H | cbv [zden nth]; lia | cbv [zden nth]; rewrite ?length_map; lia ] end
              | match goal with H : u8arr segs m ?A ?bs |- _ =>
                  apply (zr_ok_bytes_at segs zv xs m a n b c A bs);
                  [ vm_compute; reflexivity | vm_compute; reflexivity | vm_compute; reflexivity
                  | kx_arith | kx_arith | kx_arith | exact (proj1 H) | cbv [zden nth]; lia | cbv [zden nth]; rewrite ?length_map; lia ] end
              | idtac ]
      end
  end.

